KARMOLAB_LAZY_META_BY_ID['burnnote'].lazyScriptPaths
KARMOLAB_WIDGET_SCRIPT_BASE          // + 위 경로 + '.js' 가 실제 주소

// 지금 등록된 도구 훑기
Toolbox.getTools().length

function register(config) {
  const idx = tools.findIndex((t) => t.id === config.id);
  if (idx < 0) {                       // 처음 보는 도구
    tools.push(config);
    rebuildToolPageIfInDom(config.id); // 미리 그려 둔 화면을 살아 있는 것으로 교체
    return;
  }
  const wasDeferred = !!tools[idx]._deferred;
  if (!wasDeferred) disposeTool(config.id);   // 옛 것의 타이머·리스너를 먼저 거둔다
  tools[idx] = wasDeferred ? { ...config, _deferred: false } : config;
  rebuildToolPageIfInDom(config.id);
}

Toolbox.register({
  ...Toolbox.getLazyWidgetPublicMeta('mywidget'),
  tabs: [{
    id: 'app',
    build(container: HTMLElement): void {
      const ac = new AbortController();
      const timer = setInterval(tick, 1000);
      document.addEventListener('keydown', onKey, { signal: ac.signal });

      // 이 도구가 닫힐 때 불린다
      (container as any).__dispose = () => { ac.abort(); clearInterval(timer); };
    }
  }]
});
